// Top 30 LinkedIn influencers to track
const influencers = [
  {
    name: "Harvey Li",
    linkedin_username: "harvey-l-1357a418a",
    linkedin_url: "https://www.linkedin.com/in/harvey-l-1357a418a/",
    category: "business"
  },
  {
    name: "Linas Beliunas",
    linkedin_username: "linasbeliunas",
    linkedin_url: "https://www.linkedin.com/in/linasbeliunas/",
    category: "fintech"
  }
];

console.log(`Tracking ${influencers.length} influencers`);

return influencers.map(i => ({ json: i }));

const items = $input.all();

return items.map((item, index) => {
  const linkedinUrl = item.json.linkedin_url;
  let publicIdentifier = null;

  const pattern = /linkedin\.com\/in\/([^\/\?]+)/;
  const match = linkedinUrl ? linkedinUrl.match(pattern) : null;

  if (match) {
    publicIdentifier = match[1];
  }

  // Calculate row number based on array index + 2 (for header row)
  const rowNumber = index + 2;

  return {
    json: {
      ...item.json,
      public_identifier: publicIdentifier,
      row_number: rowNumber,
      processed_at: new Date().toISOString()
    }
  };
});

const allInputs = $input.all();
const posts = [];

// Collect all posts from all influencers
for (const input of allInputs) {
  const response = input.json;

  // Unipile returns nested structure
  if (response.items && Array.isArray(response.items)) {
    for (const post of response.items) {
      posts.push({
        ...post,
        influencer_name: post.author?.name || 'Unknown',
        influencer_username: post.author?.public_identifier || 'unknown',
        influencer_url: `https://www.linkedin.com/in/${post.author?.public_identifier || 'unknown'}`,
        category: 'general' // Will be added from influencer list later
      });
    }
  }
}

console.log(`Collected ${posts.length} total posts from Unipile`);

if (posts.length === 0) {
  console.log('No posts collected from influencers');
  return [];
}

// Parse relative time to check freshness
function isRecent(dateStr) {
  if (!dateStr) return false;

  const lower = dateStr.toLowerCase();

  // "12h", "5h", "1h" = recent
  if (lower.includes('h')) {
    const hours = parseInt(lower.match(/(\d+)h/)?.[1] || '999');
    return hours <= 24;
  }

  // "1d", "2d" = check days
  if (lower.includes('d')) {
    const days = parseInt(lower.match(/(\d+)d/)?.[1] || '999');
    return days <= 1;
  }

  // "5m", "30m" = very recent
  if (lower.includes('m')) {
    return true;
  }

  return false;
}

// Filter to last 24 hours using relative time
const recentPosts = posts.filter(post => {
  const isFresh = isRecent(post.date);
  return isFresh && post.text && post.text.length > 50;
});

console.log(`Filtered to ${recentPosts.length} posts from last 24 hours`);

if (recentPosts.length === 0) {
  console.log('No posts from last 24 hours');
  return [];
}

// Sort by engagement (likes + comments + shares)
recentPosts.sort((a, b) => {
  const engagementA = (a.reaction_counter || 0) + (a.comment_counter || 0) + (a.repost_counter || 0);
  const engagementB = (b.reaction_counter || 0) + (b.comment_counter || 0) + (b.repost_counter || 0);
  return engagementB - engagementA;
});

// Add engagement metrics
const enrichedPosts = recentPosts.map(post => ({
  ...post,
  total_engagement: (post.reaction_counter || 0) + (post.comment_counter || 0) + (post.repost_counter || 0),
  engagement_rate: ((post.reaction_counter || 0) + (post.comment_counter || 0)) / Math.max(post.impressions_counter || 1, 1),
  filtered_at: new Date().toISOString(),
  // Add image URL if exists
  image_url: post.attachments?.[0]?.url || null,
  has_video: post.attachments?.some(a => a.type === 'video') || false
}));

console.log('Top 5 posts by engagement:');
enrichedPosts.slice(0, 5).forEach((p, i) => {
  console.log(`${i + 1}. ${p.influencer_name}: ${p.total_engagement} engagement - "${p.text.substring(0, 60)}..."`);
});

return enrichedPosts.map(p => ({ json: p }));

// Extract image URL from Unsplash response
const response = $input.first().json;
let imageUrl = null;

if (response?.results?.length > 0) {
  imageUrl = response.results[0].urls.regular;
  console.log('✅ Found image:', imageUrl);
} else {
  console.log('⚠️ No image found, will post without image');
}

return [{
  json: {
    image_url: imageUrl,
    has_image: !!imageUrl
  }
}];

/**
 * n8n Function node script
 * Goal:
 * - Trust ChatGPT's explicit `best_post` selection (by `post_id`)
 * - Then fetch the matching post from `analyzed_posts` to get full details/content
 * - Do NOT "pick max score" (prevents ties / multiple >40 from changing selection)
 *
 * Output:
 * - best_post_id
 * - best_total_score
 * - best_original_text
 * - best_author
 * - best_recommended_action
 * - best_confidence
 * - best_post (merged, full object)
 */

function safeJsonParse(x) {
  if (typeof x === "string") {
    try { return JSON.parse(x); } catch { return null; }
  }
  return x ?? null;
}

const root = $json;

// 1) Get ChatGPT content payload
let content = root?.choices?.[0]?.message?.content;
content = safeJsonParse(content)
  ?? safeJsonParse(root?.message?.content)
  ?? safeJsonParse(root?.content)
  ?? safeJsonParse(root?.data?.choices?.[0]?.message?.content);

if (!content) {
  throw new Error("Could not find ChatGPT message content. Check the node output path.");
}

const analyzed = Array.isArray(content.analyzed_posts) ? content.analyzed_posts : [];
const bestFromModel = content.best_post ? safeJsonParse(content.best_post) : null;

if (!bestFromModel || bestFromModel.post_id == null) {
  throw new Error("ChatGPT output missing `best_post.post_id`. Ensure your prompt requires it.");
}

const bestPostId = String(bestFromModel.post_id);

// 2) Find the matching analyzed post by post_id
const analyzedMatch = analyzed.find(p => String(p?.post_id) === bestPostId) || null;

// 3) Build a merged best_post object:
// Prefer analyzed_posts fields for detailed scoring/reasoning,
// but keep best_post fields like original_text/author/recommended_action/confidence if present.
const mergedBest = {
  ...(analyzedMatch || {}),
  ...bestFromModel,
};

// 4) Ensure original text exists (best_post.original_text preferred)
const originalText =
  mergedBest?.original_text ??
  analyzedMatch?.original_text ??
  analyzedMatch?.text ??
  null;

const out = {
  best_post_id: mergedBest?.post_id ?? bestFromModel.post_id,
  best_total_score: Number(mergedBest?.total_score ?? bestFromModel.total_score ?? null),
  best_author: mergedBest?.author ?? null,
  best_recommended_action: mergedBest?.recommended_action ?? null,
  best_confidence: mergedBest?.confidence ?? null,
  best_post: mergedBest,

  // Convenience flags for IF node routing:
  should_publish:
    mergedBest?.recommended_action === "research_and_publish" ||
    mergedBest?.recommended_action === "research_and_post",

  meets_threshold: Number(mergedBest?.total_score ?? 0) >= 40
};

return [{ json: out }];

/**
 * n8n Code node
 * Compares Unipile posts ($input) against "Get Used Posts from Sheet" output
 * Flags duplicates by:
 *  - numeric LinkedIn activity ID (best signal)
 *  - canonical URL match (utm stripped)
 */

// ---------- helpers ----------
const isNonEmpty = (v) => v !== null && v !== undefined && String(v).trim() !== "";

const norm = (v) => String(v ?? "").trim().toLowerCase();

function extractDigits(str) {
  const m = String(str ?? "").match(/(\d{10,})/);
  return m ? m[1] : null;
}

// social_id examples:
// urn:li:activity:7419014408254709760
// urn:li:ugcPost:7419456267800231936  (not always same as activity id)
function extractIdFromSocialId(socialId) {
  if (!isNonEmpty(socialId)) return null;
  // grab last numeric group
  const m = String(socialId).match(/urn:li:(?:activity|ugcPost):(\d{10,})/i);
  return m?.[1] ?? extractDigits(socialId);
}

// share_url example includes:
// ...activity-7419014408254709760-SG2e?utm_source=...
function extractActivityIdFromShareUrl(url) {
  if (!isNonEmpty(url)) return null;
  const s = String(url);

  let m = s.match(/activity-(\d{10,})/i);
  if (m?.[1]) return m[1];

  m = s.match(/activity\/(\d{10,})/i);
  if (m?.[1]) return m[1];

  // fallback: any long digit sequence
  return extractDigits(s);
}

function canonicalizeUrl(raw) {
  if (!isNonEmpty(raw)) return null;
  try {
    const u = new URL(String(raw).trim());
    u.hash = "";
    u.search = ""; // strips utm params etc
    u.hostname = u.hostname.replace(/^www\./i, "");
    u.pathname = u.pathname.replace(/\/+$/, "");
    return (u.origin + u.pathname).toLowerCase();
  } catch {
    return String(raw).trim().toLowerCase().split("?")[0].split("#")[0];
  }
}

// Build a canonical ID set for any record (sheet row OR unipile post)
function collectCanonicalIds(obj) {
  const out = [];

  // direct numeric id field
  if (isNonEmpty(obj.id)) out.push(norm(obj.id));

  // your sheet might have these variations
  if (isNonEmpty(obj.LinkedInPostId)) out.push(norm(obj.LinkedInPostId));
  if (isNonEmpty(obj.LinkedInPostID)) out.push(norm(obj.LinkedInPostID));
  if (isNonEmpty(obj.linkedInPostId)) out.push(norm(obj.linkedInPostId));
  if (isNonEmpty(obj.linkedinPostId)) out.push(norm(obj.linkedinPostId));

  if (isNonEmpty(obj.unique_post_id)) out.push(norm(obj.unique_post_id));
  if (isNonEmpty(obj.post_id)) out.push(norm(obj.post_id));

  // Unipile specific
  if (isNonEmpty(obj.social_id)) {
    const fromUrn = extractIdFromSocialId(obj.social_id);
    if (isNonEmpty(fromUrn)) out.push(norm(fromUrn));
    out.push(norm(obj.social_id)); // keep the urn too (extra safety)
  }

  // from share_url (activity-<id>)
  const fromUrl = extractActivityIdFromShareUrl(obj.share_url || obj.post_url || obj.url);
  if (isNonEmpty(fromUrl)) out.push(norm(fromUrl));

  // normalize “best-7419...” -> "7419..." too
  for (const v of [...out]) {
    const digits = extractDigits(v);
    if (isNonEmpty(digits)) out.push(norm(digits));
  }

  // dedupe
  return [...new Set(out.filter(isNonEmpty))];
}

function collectCanonicalUrls(obj) {
  const candidates = [
    obj.share_url,
    obj.post_url,
    obj.url,
  ].filter(isNonEmpty);

  return [...new Set(candidates.map(canonicalizeUrl).filter(isNonEmpty))];
}

// ---------- load used sheet rows correctly ----------
const usedRows = $("Get Used Posts from Sheet").all().map((it) => it.json);

// Create lookup sets
const usedIdSet = new Set();
const usedUrlSet = new Set();

for (const row of usedRows) {
  for (const id of collectCanonicalIds(row)) usedIdSet.add(id);
  for (const u of collectCanonicalUrls(row)) usedUrlSet.add(u);
}

// ---------- process incoming Unipile items ----------
return $input.all().map((item) => {
  const post = item.json;

  const postIds = collectCanonicalIds(post);
  const postUrls = collectCanonicalUrls(post);

  const matchedId = postIds.find((id) => usedIdSet.has(id)) || null;
  const matchedUrl = postUrls.find((u) => usedUrlSet.has(u)) || null;

  const isDuplicate = Boolean(matchedId || matchedUrl);

  return {
    json: {
      ...post,
      is_duplicate: isDuplicate,
      duplicate_match: {
        matched_id: matchedId,
        matched_url: matchedUrl,
        checked_ids: postIds,     // useful for debugging, remove later if you want
        checked_urls: postUrls,   // useful for debugging, remove later if you want
      },
      flagged_reason: isDuplicate
        ? `Post already exists (${matchedId ? `ID: ${matchedId}` : `URL: ${matchedUrl}`})`
        : "New post - safe to rate",
    },
  };
});

const json = $input.first().json;

// Pull the actual content - note exact field name 'LInkedin Post' (capital I)
const title = json.title || json.headline || json.name || '';

const postContent = json['LInkedin Post'] 
  || json['Linkedin Post']
  || json['linkedin Post']
  || json.linkedinPost 
  || json.post 
  || '';

const snippet = json.contentSnippet 
  || json.summary 
  || json.description
  || json.content
  || postContent
  || '';

// Use post content as the primary source for query building
const rawText = postContent || title || snippet;

// Extract meaningful keywords from the post
const stopWords = new Set([
  'the','a','an','and','or','but','in','on','at','to','for','of','with',
  'is','are','was','were','be','been','being','have','has','had','do',
  'does','did','will','would','could','should','may','might','shall',
  'that','this','these','those','it','its','i','we','you','they','he',
  'she','what','which','who','how','when','where','why','just','out',
  'by','from','as','so','if','not','no','up','all','also','than','then',
  'been','into','about','after','before','between','same','our','their'
]);

// Get first sentence — preserve the full first sentence
const firstSentence = rawText
  .replace(/\\n/g, ' ')
  .replace(/\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .match(/.*?(?:[.!?…](?=\s|$)|$)/)?.[0]
  ?.trim() || '';

// Use the full first sentence as the search query
const searchQuery = firstSentence
  .replace(/[“”"]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  || title
  || 'artificial intelligence news';

console.log('Available fields:', Object.keys(json));
console.log('Post content preview:', postContent.slice(0, 100));
console.log('Search query built:', searchQuery);

const fallbackImageUrl = 'https://withagi.space/og-image.png';

return [{
  json: {
    ...json,
    title,
    snippet,
    fallbackImageUrl,
