const json = $input.first().json;

const fallbackImageUrl = 'https://withagi.space/og-image.png';

const imageOptions = json.imageOptions || json.images || json.results || [];

// Only allow public HTTPS image URLs
const validImages = imageOptions.filter(img => {
  const url = img.url || img.imageUrl || img.thumbnail || '';

  if (!url) return false;

  // Must be public HTTPS
  if (!url.startsWith('https://')) return false;

  // Block internal/local/blob/data URLs
  if (
    url.startsWith('x-raw-image://') ||
    url.startsWith('blob:') ||
    url.startsWith('file:') ||
    url.startsWith('data:') ||
    url.includes('localhost') ||
    url.includes('127.0.0.1')
  ) {
    return false;
  }

  // Optional: prefer real image file URLs
  const looksLikeImage =
    url.match(/\.(jpg|jpeg|png|webp|gif)(\?|$)/i) ||
    url.includes('pbs.twimg.com/media') ||
    url.includes('images.unsplash.com') ||
    url.includes('cloudinary.com') ||
    url.includes('wp.com') ||
    url.includes('cdn');

  return looksLikeImage;
});

// If no valid image exists, force fallback
const finalImageOptions = validImages.length > 0
  ? validImages
  : [{
      index: 0,
      url: fallbackImageUrl,
      title: 'Default WithAGI Image',
      source: 'Fallback',
      width: 1200,
      height: 630,
      isLandscape: true
    }];

return [{
  json: {
    ...json,
    imageOptions: finalImageOptions,
    hasValidImages: validImages.length > 0,
    fallbackImageUrl
  }
}];
